"""labels.csv reading/writing (torch-free)."""
import csv
import os

SPLITS = ("train", "val", "test")
HEADER = ["video", "split", "start_s", "end_s", "label"]
COMMENT = ("# video,split,start_s,end_s,label   (end_s blank = to end of video)\n"
           "# Normally generated by make_labels.py; edit by hand to label time ranges inside a video.\n"
           "# Same video may appear in several rows/splits as long as time ranges do not overlap.\n")


def read_rows(path, classes):
    if not os.path.exists(path):
        return []
    with open(path, newline="", encoding="utf-8") as f:
        lines = [l for l in f if l.strip() and not l.lstrip().startswith("#")]
    rows = []
    for n, r in enumerate(csv.DictReader(lines), 2):
        r = {k.strip(): (v or "").strip() for k, v in r.items()}
        if r["label"] not in classes:
            raise SystemExit(f"{path} row {n}: label '{r['label']}' not in {list(classes)}")
        if r["split"] not in SPLITS:
            raise SystemExit(f"{path} row {n}: split must be one of {SPLITS}")
        end = None if r["end_s"].lower() in ("", "end") else float(r["end_s"])
        rows.append({"video": os.path.normpath(r["video"]), "split": r["split"], "label": r["label"],
                     "start": float(r["start_s"] or 0), "end": end})
    return rows


def append_rows(path, rows):
    new = not os.path.exists(path)
    if not new:
        with open(path, "rb") as f:                 # make sure the last line ends with a newline
            data = f.read()
        if data and not data.endswith(b"\n"):
            with open(path, "ab") as f:
                f.write(b"\n")
    with open(path, "a", newline="", encoding="utf-8") as f:
        if new:
            f.write(COMMENT)
        w = csv.writer(f, lineterminator="\n")
        if new:
            w.writerow(HEADER)
        for r in rows:
            w.writerow([r["video"].replace("\\", "/"), r["split"], f"{r['start']:g}",
                        "" if r["end"] is None else f"{r['end']:g}", r["label"]])


def check_overlaps(rows):
    inf = float("inf")
    for i, a in enumerate(rows):
        for b in rows[i + 1:]:
            if os.path.normcase(a["video"]) != os.path.normcase(b["video"]):
                continue
            a_end = inf if a["end"] is None else a["end"]
            b_end = inf if b["end"] is None else b["end"]
            if a["start"] < b_end and b["start"] < a_end:
                raise SystemExit(
                    f"labels.csv overlap in {a['video']}: [{a['start']:g},{a['end']}] ({a['split']}/{a['label']}) "
                    f"vs [{b['start']:g},{b['end']}] ({b['split']}/{b['label']}). Fix the ranges.")
